// The support script generated GDScript preloads (docs/more-languages.md, "GDScript"): sets, the
// semantics' number formatting and conversions, event dispatchers, the latent queue, and errors.
// GDScript has no exceptions, so vg.fail records the error, and generated code returns after any
// statement that may fail; printing and Delay do nothing once a run has failed.
//
// A copy sits next to every generated file (a companion file), so each preloads it by its own name.
// The run's state lives on Engine's metadata, so the copies in different folders share it, and
// values are recognized by the methods they have (vg_kind, vg_fields, vg_interfaces), not by the
// copy that made them.
export const GDSCRIPT_RUNTIME_FILE = 'vgraph_runtime.gd';

export function gdscriptRuntime(): string {
  return `${GDSCRIPT_RUNTIME}\n`;
}

const GDSCRIPT_RUNTIME = String.raw`# Support code for GDScript generated by Blueprint Visual Scripting (docs/more-languages.md).
# Generated scripts preload it as "vgraph_runtime.gd". Do not edit: it is rewritten when graphs are compiled.
extends RefCounted


# ---- The run's state ------------------------------------------------------------------------------

static func _state() -> Dictionary:
	if not Engine.has_meta("vgraph_run"):
		Engine.set_meta("vgraph_run", {"failed": false, "failure": "", "pending": [], "order": 0})
	return Engine.get_meta("vgraph_run")


# A fresh run (each test runs on its own).
static func reset() -> void:
	Engine.set_meta("vgraph_run", {"failed": false, "failure": "", "pending": [], "order": 0})


# Stops the run with the message: generated code returns after a failed statement. Returns
# fallback, so a snippet can return it: return vg.fail("Divide by zero", 0.0).
static func fail(message: String, fallback = null):
	var state := _state()
	if not state["failed"]:
		state["failed"] = true
		state["failure"] = message
	return fallback


static func failed() -> bool:
	return _state()["failed"]


static func failure() -> String:
	return _state()["failure"]


static func print_line(text: String) -> void:
	if not failed():
		print(text)


# ---- Sets -----------------------------------------------------------------------------------------
# Sets have no order of their own: they print and turn into arrays in ascending order.

class VgSet:
	extends RefCounted
	var items := {}

	func vg_kind() -> String:
		return "set"

	func add(item) -> void:
		items[item] = true

	func remove(item) -> bool:
		return items.erase(item)

	func clear() -> void:
		items.clear()

	func contains(item) -> bool:
		return items.has(item)

	func size() -> int:
		return items.size()

	func sorted() -> Array:
		var list := items.keys()
		list.sort()
		return list


static func set_of(items: Array) -> VgSet:
	var result := VgSet.new()
	for item in items:
		result.add(item)
	return result


# ---- Event dispatchers ----------------------------------------------------------------------------
# Bound events (an object and its function's name) run in the order they were bound, each once.

class Dispatcher:
	extends RefCounted
	var handlers: Array = []

	func bind(object, method: String) -> void:
		for handler in handlers:
			if handler[0] == object and handler[1] == method:
				return
		handlers.append([object, method])

	func unbind(object, method: String) -> void:
		for i in handlers.size():
			if handlers[i][0] == object and handlers[i][1] == method:
				handlers.remove_at(i)
				return

	func clear() -> void:
		handlers.clear()

	func broadcast(args: Array) -> void:
		for handler in handlers.duplicate():
			handler[0].callv(handler[1], args)


static func dispatcher() -> Dispatcher:
	return Dispatcher.new()


# Cast To an interface: whether the object's class (or an ancestor) implements it.
static func implements(value, interface) -> bool:
	return value is Object and value != null and value.has_method("vg_interfaces") and value.vg_interfaces().has(interface)


# ---- Latent actions -------------------------------------------------------------------------------
# Delay's actions, of every class, run from one queue in the order they fall due, once Start (and
# Main) have returned.

static func delay(seconds: float, action: Callable) -> void:
	if failed():
		return
	var state := _state()
	state["order"] += 1
	state["pending"].append({"due": Time.get_ticks_usec() + int(maxf(0.0, seconds) * 1000000.0), "order": state["order"], "action": action})


static func run_latent_actions() -> void:
	var pending: Array = _state()["pending"]
	while not pending.is_empty() and not failed():
		pending.sort_custom(func(a, b): return a["due"] < b["due"] or (a["due"] == b["due"] and a["order"] < b["order"]))
		var next: Dictionary = pending.pop_front()
		var wait: int = next["due"] - Time.get_ticks_usec()
		if wait > 0:
			OS.delay_usec(wait)
		next["action"].call()


# ---- Values (docs/semantics.md) -------------------------------------------------------------------

# Numbers as text by JavaScript's rules. String.num_scientific gives the shortest digits that read
# back exactly; they are laid out as JavaScript does.
static func format_number(x) -> String:
	if x is int:
		return str(x)
	if is_nan(x):
		return "NaN"
	if is_inf(x):
		return "Infinity" if x > 0 else "-Infinity"
	if x == 0:
		return "0"
	var text := String.num_scientific(absf(x))
	var sign := "-" if x < 0 else ""
	var exponent := 0
	var e := text.find("e")
	if e >= 0:
		exponent = int(text.substr(e + 1))
		text = text.substr(0, e)
	var dot := text.find(".")
	var whole := text if dot < 0 else text.substr(0, dot)
	var fraction := "" if dot < 0 else text.substr(dot + 1)
	var digits := whole + fraction
	var point := whole.length() + exponent
	while digits.begins_with("0"):
		digits = digits.substr(1)
		point -= 1
	while digits.ends_with("0"):
		digits = digits.substr(0, digits.length() - 1)
	if digits.is_empty():
		return "0"
	if digits.length() <= point and point <= 21:
		return sign + digits + "0".repeat(point - digits.length())
	if 0 < point and point <= 21:
		return sign + digits.substr(0, point) + "." + digits.substr(point)
	if -6 < point and point <= 0:
		return sign + "0." + "0".repeat(-point) + digits
	var mantissa := digits if digits.length() == 1 else digits.substr(0, 1) + "." + digits.substr(1)
	return sign + mantissa + "e" + ("+" if point > 0 else "-") + str(absi(point - 1))


static func _quote(text: String) -> String:
	var out := "\""
	for i in text.length():
		var c := text.unicode_at(i)
		match c:
			0x22:
				out += "\\\""
			0x5C:
				out += "\\\\"
			0x0A:
				out += "\\n"
			0x0D:
				out += "\\r"
			0x09:
				out += "\\t"
			0x08:
				out += "\\b"
			0x0C:
				out += "\\f"
			_:
				out += ("\\u%04x" % c) if c < 0x20 else String.chr(c)
	return out + "\""


static func _key_text(key) -> String:
	return key if key is String else format(key)


# Containers and structs print as JSON: sets in ascending order, maps in the order keys were added.
static func json(value) -> String:
	if value == null:
		return "null"
	if value is bool:
		return "true" if value else "false"
	if value is int:
		return str(value)
	if value is float:
		return "null" if is_nan(value) or is_inf(value) else format_number(value)
	if value is String:
		return _quote(value)
	if value is Array:
		var parts := PackedStringArray()
		for item in value:
			parts.append(json(item))
		return "[" + ",".join(parts) + "]"
	if value is Dictionary:
		var parts := PackedStringArray()
		for key in value:
			parts.append(_quote(_key_text(key)) + ":" + json(value[key]))
		return "{" + ",".join(parts) + "}"
	if value is Object and value.has_method("vg_kind"):
		return json(value.sorted())
	if value is Object and value.has_method("vg_fields"):
		var parts := PackedStringArray()
		for field in value.vg_fields():
			parts.append(_quote(field[0]) + ":" + json(field[1]))
		return "{" + ",".join(parts) + "}"
	return _quote(str(value))


static func format(value) -> String:
	if value == null:
		return ""
	if value is bool:
		return "true" if value else "false"
	if value is int or value is float:
		return format_number(value)
	if value is String:
		return value
	return json(value)


# Text as a number, as JavaScript's Number() reads it: blank is 0, anything else not a number NaN.
static func to_number(value) -> float:
	if value == null:
		return 0.0
	if value is bool:
		return 1.0 if value else 0.0
	if value is int or value is float:
		return float(value)
	if not value is String:
		return NAN
	var text: String = value.strip_edges()
	if text.is_empty():
		return 0.0
	if text == "Infinity" or text == "+Infinity":
		return INF
	if text == "-Infinity":
		return -INF
	if text.is_valid_float():
		return text.to_float()
	if text.begins_with("0x") and text.substr(2).is_valid_hex_number():
		return float(text.hex_to_int())
	return NAN


# Truth as the semantics define it: false, null, 0, NaN and empty text are false.
static func to_boolean(value) -> bool:
	if value == null:
		return false
	if value is bool:
		return value
	if value is int:
		return value != 0
	if value is float:
		return value != 0 and not is_nan(value)
	if value is String:
		return not value.is_empty()
	return true`;
